# -*- coding: utf-8 -*-
"""MiniMax H3 · 双图参考版（Ref2VA）· 20 种风格整段提示词。

对应单图版 zoey_minimax_h3_styles.py 的 STYLE_MAP，但这里是「双图版」：
- <Picture 1> = 主体参考（保持真实外观、身份、整个真实环境场景全程不变，不作风格化）
- <Picture 2> = 风格化主体参考（约一个半巴掌大小；保留其物种/轮廓可辨识、绝不变物种，但整体
                「从零重画成」所选风格的具体工序，而非给照片加滤镜；完全扁平2D、卡通化、非写实）

用途：给 MiniMax H3 参考转视频（Ref2VA）模式。图1人物与图2风格化主体全程互动，
一镜到底零切镜、落点紧贴主体/只落真实场景、不上墙。
占位符：[MORPH]变形成什么  [ESCAPE_ROUTE]逃跑路线  [FINAL]最终形态/落点  [MOOD]情绪
"""

# 图2行中文开头（共享）：留住物种可辨识，其余全部由该风格从零重画
_DUAL = ("所绘主体的整体约一个半巴掌大小、可爱讨喜；保留参考图2里这个主体的物种与轮廓可辨识——"
         "它必须始终是同一个物种/对象，绝不能变成另一种动物、绝不凭空生出别的物种；但整体必须像用"
         "{MED}把整个主体从头重画一遍：{FD}；不是给真实照片加滤镜，而是整幅画面就是一幅{STYLE}；它必须"
         "是完全扁平化的2D图形，彻底消除体积感、立体感、景深与三维摄影渲染，像平面的贴纸/插画而不是"
         "立体对象；这必须是彻底、鲜明、夸张的卡通化重绘，与真实照片截然不同，绝非半写实、绝非只是滤镜；"
         "它始终是同一个主体，绝不会变成另一种动物、绝不凭空生出非参考里的东西")

# 落点句（精简版）：紧贴主体、只落真实场景、不上墙
_SETTLE = ("settles into [FINAL] right beside the subject within <Picture 1>'s real scene — never on any wall. ")

# 图2风格子句英文骨架
def _body(features):
    return (f"but is rendered at about the size of one and a half palms, cute and endearing, as the same "
            f"recognizable species and silhouette as <Picture 2> (never turning into a different animal or object, "
            f"never a new species), yet is re-drawn from scratch as a full {features} — not a photo with a "
            f"filter — the stylization must cover the subject entirely, outlines, fill, "
            f"shading and all, leaving zero photorealistic remains, no original photo colors, no real texture, "
            f"no real lighting, no volume, no 3D depth, no perspective, no painterly height; the result must read "
            f"as a completely flat 2D graphic, the subject sitting on a single plane like a sticker or flat "
            f"illustration, never a three-dimensional object — a boldly stylized, cartoon-like picture, heavily "
            f"simplified and exaggerated, unmistakably different from the photograph, never merely a photo with a "
            f"filter — with only the subject's silhouette carried over from the photo.")


